namespace DQTech {
public class Settings { public string id="",token="",name="",lastAttempt="",lastSuccess=""; public bool consent=false; }
public class ApiException:Exception { public int Status; public ApiException(int status):base(status==403?"Chưa được duyệt, chưa tới hạn, hết hạn hoặc đã bị kết thúc. Không sửa dữ liệu.":status==401?"Thông tin đăng ký không hợp lệ.":"Portal không sẵn sàng. Không sửa dữ liệu."){Status=status;} }
public static class Engine {
 public static readonly string Root=Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.CommonApplicationData),"DQTech","CSMTool");
 public static readonly string Exe=Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.ProgramFiles),"DQTech","CSMTool","DQTech-CSM-Tool.exe");
 public const string Endpoint="https://dqtech.org/api/net-game?action=";
 public static readonly string[] Names={"intoptiontb.frm","intoptiontb.MYD","intoptiontb.MYI"};
 public static JavaScriptSerializer Json=new JavaScriptSerializer();
 public static Action<string> Output=s=>{};
 public static void Init(){Directory.CreateDirectory(Root);var acl=new DirectorySecurity();acl.SetAccessRuleProtection(true,false);foreach(var sid in new[]{WellKnownSidType.BuiltinAdministratorsSid,WellKnownSidType.LocalSystemSid})acl.AddAccessRule(new FileSystemAccessRule(new SecurityIdentifier(sid,null),FileSystemRights.FullControl,InheritanceFlags.ContainerInherit|InheritanceFlags.ObjectInherit,PropagationFlags.None,AccessControlType.Allow));Directory.SetAccessControl(Root,acl);ServicePointManager.SecurityProtocol=SecurityProtocolType.Tls12;}
 public static void Log(string s){Output(s);File.AppendAllText(Path.Combine(Root,"tool.log"),DateTimeOffset.Now.ToString("o")+" "+s+Environment.NewLine);}
 public static Settings Load(){string p=Path.Combine(Root,"settings.bin");if(!File.Exists(p))return new Settings();return Json.Deserialize<Settings>(Encoding.UTF8.GetString(ProtectedData.Unprotect(File.ReadAllBytes(p),null,DataProtectionScope.LocalMachine)));}
 public static void Save(Settings s){string p=Path.Combine(Root,"settings.bin"),tmp=p+".tmp";File.WriteAllBytes(tmp,ProtectedData.Protect(Encoding.UTF8.GetBytes(Json.Serialize(s)),null,DataProtectionScope.LocalMachine));if(File.Exists(p))File.Replace(tmp,p,null);else File.Move(tmp,p);}
 public static Dictionary<string,object> Api(string action,object payload){var req=(HttpWebRequest)WebRequest.Create(Endpoint+action);req.Method="POST";req.ContentType="application/json";req.UserAgent="DQTech-CSM-Tool/1.0 (Windows)";req.Timeout=20000;req.ReadWriteTimeout=20000;req.AllowAutoRedirect=false;byte[] data=Encoding.UTF8.GetBytes(Json.Serialize(payload));req.ContentLength=data.Length;using(var stream=req.GetRequestStream())stream.Write(data,0,data.Length);try{using(var res=(HttpWebResponse)req.GetResponse()){if(res.StatusCode!=HttpStatusCode.OK&&res.StatusCode!=HttpStatusCode.Created)throw new Exception("Phản hồi Portal không hợp lệ.");using(var reader=new StreamReader(res.GetResponseStream()))return Json.Deserialize<Dictionary<string,object>>(reader.ReadToEnd());}}catch(WebException e){var response=e.Response as HttpWebResponse;if(response!=null){int code=(int)response.StatusCode;response.Dispose();throw new ApiException(code);}throw new Exception("Không kết nối được Portal. Không sửa dữ liệu.");}}
 public static string Hash(byte[] b){using(var h=SHA256.Create())return BitConverter.ToString(h.ComputeHash(b)).Replace("-","").ToLowerInvariant();}
 public static string HashFile(string p){return Hash(File.ReadAllBytes(p));}
 public static void Command(string args){var p=Process.Start(new ProcessStartInfo("schtasks.exe",args){UseShellExecute=false,CreateNoWindow=true,RedirectStandardOutput=true,RedirectStandardError=true});string output=p.StandardOutput.ReadToEnd()+p.StandardError.ReadToEnd();if(!p.WaitForExit(30000)||p.ExitCode!=0)throw new Exception("Không cấu hình được lịch Windows: "+output);}
 public static bool StartupEnabled(){return File.Exists(Path.Combine(Root,"startup.enabled"));}
 public static void Startup(bool enabled){const string task="DQTech-CSM-Tool";if(enabled){Directory.CreateDirectory(Path.GetDirectoryName(Exe));if(!String.Equals(Application.ExecutablePath,Exe,StringComparison.OrdinalIgnoreCase))File.Copy(Application.ExecutablePath,Exe,true);string sid=WindowsIdentity.GetCurrent().User.Value;foreach(var kind in new[]{"Logon","Daily"}){string xml=Path.Combine(Root,"task-"+kind+".xml");using(var w=XmlWriter.Create(xml,new XmlWriterSettings{Indent=true,Encoding=Encoding.Unicode})){w.WriteStartDocument();w.WriteStartElement("Task","http://schemas.microsoft.com/windows/2004/02/mit/task");w.WriteAttributeString("version","1.2");w.WriteStartElement("Triggers");if(kind=="Logon"){w.WriteStartElement("LogonTrigger");w.WriteElementString("UserId",sid);w.WriteElementString("Delay","PT1M");}else{w.WriteStartElement("CalendarTrigger");w.WriteElementString("StartBoundary",DateTime.Today.AddHours(9).ToString("yyyy-MM-ddTHH:mm:ss"));w.WriteStartElement("ScheduleByDay");w.WriteElementString("DaysInterval","1");w.WriteEndElement();}w.WriteEndElement();w.WriteEndElement();w.WriteStartElement("Principals");w.WriteStartElement("Principal");w.WriteAttributeString("id","Author");w.WriteElementString("UserId",sid);w.WriteElementString("LogonType","InteractiveToken");w.WriteElementString("RunLevel","HighestAvailable");w.WriteEndElement();w.WriteEndElement();w.WriteStartElement("Settings");w.WriteElementString("MultipleInstancesPolicy","IgnoreNew");w.WriteElementString("DisallowStartIfOnBatteries","false");w.WriteElementString("StopIfGoingOnBatteries","false");w.WriteElementString("StartWhenAvailable","true");w.WriteElementString("ExecutionTimeLimit","PT10M");w.WriteEndElement();w.WriteStartElement("Actions");w.WriteAttributeString("Context","Author");w.WriteStartElement("Exec");w.WriteElementString("Command",Exe);w.WriteElementString("Arguments","--auto");w.WriteEndElement();w.WriteEndElement();w.WriteEndElement();w.WriteEndDocument();}Command("/Create /TN \""+task+"-"+kind+"\" /XML \""+xml+"\" /F");}File.WriteAllText(Path.Combine(Root,"startup.enabled"),sid);}else{foreach(string kind in new[]{"Logon","Daily"}){try{Command("/Delete /TN \""+task+"-"+kind+"\" /F");}catch{}}File.Delete(Path.Combine(Root,"startup.enabled"));}}
 public static void Repair(Settings cfg){
  bool acquired=false;using(var mutex=new Mutex(false,"Global\\DQTech-CSM-Repair")){try{try{acquired=mutex.WaitOne(0);}catch(AbandonedMutexException){acquired=true;}if(!acquired)throw new Exception("Một phiên sửa đang chạy.");
   if(String.IsNullOrEmpty(cfg.id))throw new Exception("Vui lòng đăng ký tên phòng máy trước.");if(!cfg.consent)throw new Exception("Chưa xác nhận sao lưu và quyền phục hồi cấu hình trên máy này.");
   var permit=Api("check",new{id=cfg.id,token=cfg.token});long now=Convert.ToInt64(permit["serverTime"]);string day=new DateTimeOffset(1970,1,1,0,0,0,TimeSpan.Zero).AddSeconds(now).ToOffset(TimeSpan.FromHours(7)).ToString("yyyy-MM-dd");
   if(cfg.lastSuccess==day){Log("Hôm nay đã xử lý thành công. Không chạy lại.");return;}if(cfg.lastAttempt==day)throw new Exception("Hôm nay đã có lần xử lý. Nếu lỗi, tool sẽ thử lại ngày mai; không chép đè lặp lại.");
   Log("Đang tải ngầm và kiểm tra bộ phục hồi từ Portal.");var bundle=Api("bundle",new{id=cfg.id,token=cfg.token});var files=(System.Collections.IList)bundle["files"];if(files.Count!=3)throw new Exception("Bộ file không đầy đủ.");var bytes=new Dictionary<string,byte[]>();foreach(Dictionary<string,object> f in files){string name=(string)f["name"];if(!Names.Contains(name)||bytes.ContainsKey(name))throw new Exception("Tên file không hợp lệ.");var b=Convert.FromBase64String((string)f["data"]);if(b.Length>1048576||Hash(b)!=(string)f["sha256"])throw new Exception("Sai SHA-256 bộ file.");bytes.Add(name,b);}
   // Known production layout only. Never infer or write an arbitrary database path.
   string mysql=Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.ProgramFilesX86),"MySQL","MySQL Server 5.0"),target=Path.Combine(mysql,"Data","ddm");
   foreach(string n in Names)if(!File.Exists(Path.Combine(target,n)))throw new Exception("Không tìm thấy bộ intoptiontb tại "+target+". Cần kỹ thuật viên cấu hình, tool không sửa máy khác đường dẫn.");
   if(HashFile(Path.Combine(target,"intoptiontb.frm"))!=Hash(bytes["intoptiontb.frm"]))throw new Exception("Cấu trúc bảng không tương thích bộ phục hồi. Không thay file.");
   using(var service=new ServiceController("MySQL")){if(service.Status!=ServiceControllerStatus.Running)throw new Exception("MySQL chưa chạy ổn định. Không tự sửa khi dịch vụ đang lỗi.");
    string backup=Path.Combine(Root,"backups",DateTime.Now.ToString("yyyyMMdd-HHmmss"));Directory.CreateDirectory(backup);string csm=Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.ProgramFilesX86),"CSMServer","ServerSide.exe");bool reopen=false,stopped=false,copied=false,backed=false;
    // Revalidate authorization immediately before the disruptive operation.
    Api("check",new{id=cfg.id,token=cfg.token});
    foreach(var process in Process.GetProcessesByName("ServerSide")){using(process){if(!String.Equals(process.MainModule.FileName,csm,StringComparison.OrdinalIgnoreCase))throw new Exception("Tiến trình CSM không đúng đường dẫn đã cấu hình.");reopen=true;if(!process.CloseMainWindow()||!process.WaitForExit(15000))throw new Exception("CSM chưa đóng được. Hãy kết thúc giao dịch và đóng CSM trước; tool không ép tắt.");}}
    cfg.lastAttempt=day;Save(cfg);try{
     Log("Dừng MySQL để sao lưu nhất quán.");service.Stop();stopped=true;service.WaitForStatus(ServiceControllerStatus.Stopped,TimeSpan.FromSeconds(45));
     var manifest=new Dictionary<string,string>();foreach(string n in Names){string src=Path.Combine(target,n),dest=Path.Combine(backup,n);File.Copy(src,dest,false);manifest[n]=HashFile(src);if(manifest[n]!=HashFile(dest))throw new Exception("Sao lưu không khớp.");}File.WriteAllText(Path.Combine(backup,"sha256.json"),Json.Serialize(manifest));backed=true;
     // Permission must still be valid after service stop/backup. Failure restores normal service without writing.
     Api("check",new{id=cfg.id,token=cfg.token});copied=true;foreach(string n in Names){File.WriteAllBytes(Path.Combine(target,n),bytes[n]);if(HashFile(Path.Combine(target,n))!=Hash(bytes[n]))throw new Exception("Kiểm tra file sau chép thất bại.");}
     service.Start();service.WaitForStatus(ServiceControllerStatus.Running,TimeSpan.FromSeconds(45));Thread.Sleep(4000);service.Refresh();if(service.Status!=ServiceControllerStatus.Running)throw new Exception("MySQL không giữ trạng thái Running.");cfg.lastSuccess=day;Save(cfg);Log("Hoàn tất. MySQL đang chạy. Backup: "+backup);
    }catch{Log("Lỗi xử lý; khôi phục bộ file gốc nếu đã thay.");if(copied&&backed){service.Refresh();if(service.Status!=ServiceControllerStatus.Stopped){if(service.Status!=ServiceControllerStatus.StopPending)service.Stop();service.WaitForStatus(ServiceControllerStatus.Stopped,TimeSpan.FromSeconds(45));}foreach(string n in Names)File.Copy(Path.Combine(backup,n),Path.Combine(target,n),true);Log("Đã chép lại bộ sao lưu.");}throw;
    }finally{service.Refresh();if(stopped&&service.Status==ServiceControllerStatus.StopPending){service.WaitForStatus(ServiceControllerStatus.Stopped,TimeSpan.FromSeconds(45));service.Refresh();}if(stopped&&service.Status==ServiceControllerStatus.Stopped){service.Start();service.WaitForStatus(ServiceControllerStatus.Running,TimeSpan.FromSeconds(45));}if(reopen&&File.Exists(csm)&&Process.GetProcessesByName("ServerSide").Length==0)Process.Start(csm);}
   }
  }finally{if(acquired)mutex.ReleaseMutex();}}
 }
}
public class ToolForm:Form{
 TextBox name=new TextBox(),log=new TextBox();Button register=new Button(),run=new Button(),import=new Button();CheckBox startup=new CheckBox(),consent=new CheckBox();Settings cfg;bool busy=false;
 public ToolForm(bool auto){Text="DQTech • Phục hồi dữ liệu CSM";Size=new Size(700,620);MinimumSize=Size;StartPosition=FormStartPosition.CenterScreen;Font=new Font("Segoe UI",10);cfg=Engine.Load();var panel=new FlowLayoutPanel{Dock=DockStyle.Fill,FlowDirection=FlowDirection.TopDown,WrapContents=false,Padding=new Padding(22),AutoScroll=true};Controls.Add(panel);
 panel.Controls.Add(new Label{Text="DQTECH — TOOL PHỤC HỒI CSM",AutoSize=true,Font=new Font(Font.FontFamily,17,FontStyle.Bold)});panel.Controls.Add(new Label{Text="Tên phòng máy (đăng ký gói 1 tháng, tự kích hoạt)",AutoSize=true});name.Width=620;name.Text=cfg.name;panel.Controls.Add(name);register.Text="Đăng ký phòng máy";register.AutoSize=true;register.Click+=async(s,e)=>await Register();panel.Controls.Add(register);import.Text="Nhập file đăng ký từ website";import.AutoSize=true;import.Click+=(s,e)=>Import();// Registration credentials are obtained directly from Portal; no file import UI.
 consent.Text="Tôi cho phép phục hồi cấu hình CSM và đã kết thúc giao dịch.";consent.AutoSize=true;consent.Checked=cfg.consent;consent.CheckedChanged+=async(s,e)=>{cfg.consent=consent.Checked;Engine.Save(cfg);if(cfg.consent&&!String.IsNullOrEmpty(cfg.id)&&!busy)await Run();};panel.Controls.Add(consent);
 startup.Text="Tự chạy khi đăng nhập Windows trên máy tính tiền (và kiểm tra lúc 09:00)";startup.AutoSize=true;startup.Checked=Engine.StartupEnabled();startup.CheckedChanged+=(s,e)=>{try{Engine.Startup(startup.Checked);Engine.Log(startup.Checked?"Đã bật lịch tự chạy. Tối đa 1 lần/ngày.":"Đã tắt lịch tự chạy.");}catch(Exception x){MessageBox.Show(x.Message);}};panel.Controls.Add(startup);
 run.Text="Kiểm tra hạn và phục hồi";run.AutoSize=true;run.Click+=async(s,e)=>await Run();panel.Controls.Add(run);log.Multiline=true;log.ReadOnly=true;log.ScrollBars=ScrollBars.Vertical;log.Width=620;log.Height=175;panel.Controls.Add(log);var contact=new LinkLabel{Text="0977145858  •  doan.phamtg@gmail.com",AutoSize=true};contact.LinkClicked+=(s,e)=>Process.Start("https://dqtech.org/khac-phuc-loi-csm.html");panel.Controls.Add(contact);panel.Controls.Add(new Label{Text="Hết hạn / bị kết thúc / mất kết nối: không sửa. Bản sao lưu nằm trong ProgramData\\DQTech\\CSMTool.",MaximumSize=new Size(620,0),AutoSize=true});Engine.Output=s=>{if(IsHandleCreated)BeginInvoke((Action)(()=>log.AppendText(s+Environment.NewLine)));};FormClosing+=(s,e)=>{if(busy){e.Cancel=true;MessageBox.Show("Đang xử lý, không đóng ứng dụng lúc này.");}};Shown+=async(s,e)=>{if(!String.IsNullOrEmpty(cfg.id))await Run();if(auto&&!busy)Close();};
 }
 async Task Register(){if(busy)return;if(!String.IsNullOrEmpty(cfg.id)){MessageBox.Show("Máy đã đăng ký. Tool sẽ kiểm tra hạn và tự xử lý nếu hôm nay chưa chạy.");return;}if(name.Text.Trim().Length<2){MessageBox.Show("Nhập tên phòng máy.");return;}SetBusy(true);try{string room=name.Text.Trim();var v=await Task.Run(()=>Engine.Api("register",new{name=room}));cfg.id=(string)v["id"];cfg.token=(string)v["token"];cfg.name=room;Engine.Save(cfg);Engine.Log("Đăng ký thành công. Tool tự kiểm tra thời hạn trên Portal; admin có thể điều chỉnh hoặc kết thúc.");}catch(Exception e){Engine.Log(e.Message);}finally{SetBusy(false);}if(!String.IsNullOrEmpty(cfg.id)&&cfg.consent)await Run();}
 void Import(){if(busy)return;using(var d=new OpenFileDialog{Filter="Đăng ký DQTech (*.json)|*.json"})if(d.ShowDialog()==DialogResult.OK){try{var v=Engine.Json.Deserialize<Dictionary<string,object>>(File.ReadAllText(d.FileName));string id=(string)v["id"],token=(string)v["token"];if(id.Length<20||token.Length<30)throw new Exception("File đăng ký không hợp lệ.");cfg.id=id;cfg.token=token;cfg.name=(string)v["name"];name.Text=cfg.name;Engine.Save(cfg);Engine.Log("Đã nhập thông tin đăng ký. Portal vẫn phải xác nhận hạn trước mỗi lần sửa.");}catch(Exception e){MessageBox.Show(e.Message);}}}
 void SetBusy(bool v){busy=v;register.Enabled=run.Enabled=import.Enabled=startup.Enabled=consent.Enabled=!v;}
 async Task Run(){if(busy)return;SetBusy(true);try{await Task.Run(()=>Engine.Repair(cfg));}catch(Exception e){Engine.Log(e.Message);}finally{SetBusy(false);}}
}
static class Program{
 [STAThread]static int Main(string[] args){if(args.Contains("--self-test")){if(Engine.Hash(Encoding.UTF8.GetBytes("abc"))!="ba7816bf8f01cfea414140de5dae2223b00361a396177a9cb410ff61f20015ad")return 1;return 0;}Application.EnableVisualStyles();Application.SetCompatibleTextRenderingDefault(false);try{Engine.Init();Application.Run(new ToolForm(args.Contains("--auto")));return 0;}catch(Exception e){MessageBox.Show(e.Message,"DQTech");return 1;}}
}
